//! Adopted conversation/task state; pending input is not already interpreted intent.
use serde_json::{json,Value};
use std::collections::{HashMap,HashSet};
use std::sync::{Arc,Mutex,Condvar};
use crate::context::Context;
#[derive(Clone,Debug)]pub struct Request{pub goal_id:String,pub stimulus_id:String,pub raw:String,pub revision:u64,pub scope:String,pub adoption:Value,pub correction:Option<Value>,pub delivered:Option<Value>}
#[derive(Default)]pub struct Conversation{pub requests:HashMap<String,Request>,pub pending:HashSet<String>,pub captured:Vec<Value>,pub questions:Vec<Value>,pub associations:Vec<Value>,pub outputs:Vec<Value>,pub attempted_response_revision:HashMap<String,u64>,pub last_relation_node:Option<String>}
pub type Shared=Arc<(Mutex<Conversation>,Condvar)>;
pub fn new()->Shared{Arc::new((Mutex::new(Conversation::default()),Condvar::new()))}
pub fn capture(state:&Shared,ctx:&Context,event:&Value){let id=event["id"].as_str().unwrap_or("");ctx.capture(id,&json!({"text":event["text"],"revision":event["revision"],"input_class":"USER_TEXT"}));let mut s=state.0.lock().unwrap();s.pending.insert(id.into());s.captured.push(event.clone());}
fn public_intent(value:&Value)->Value{let mut out=serde_json::Map::new();for key in ["relation","target_request_id","question_id","task_id","scope","targets","handling_text","source_revisions"]{if let Some(v)=value.get(key){out.insert(key.into(),v.clone());}}Value::Object(out)}
pub fn snapshot(state:&Shared)->Value{let s=state.0.lock().unwrap();json!({"captured_inputs":s.captured,"pending_uninterpreted_inputs":s.pending,"requests":s.requests.values().map(|r|json!({"request_id":r.goal_id,"original_text":r.raw,"revision":r.revision,"scope":r.scope,"adopted":public_intent(&r.adoption),"correction":r.correction.as_ref().map(|c|json!({"event":c["event"],"adopted_intent":public_intent(&c["adopted_intent"])})),"delivered":r.delivered})).collect::<Vec<_>>(),"actually_displayed_questions":s.questions})}
pub fn request(state:&Shared,id:&str)->Option<Request>{state.0.lock().unwrap().requests.get(id).cloned()}
pub fn resolve_input(state:&Shared,event:&Value,node:Option<String>){let mut s=state.0.lock().unwrap();s.pending.remove(event["id"].as_str().unwrap_or(""));s.last_relation_node=node;drop(s);state.1.notify_all();}
pub fn wait_relations(state:&Shared,ctx:&Context,goal_id:&str){let mut s=state.0.lock().unwrap();if !s.pending.is_empty(){ctx.event("POLICY_WAIT_START",&json!({"goal_id":goal_id,"reason":"unresolved captured input may revise draft","pending":s.pending}));while !s.pending.is_empty(){s=state.1.wait(s).unwrap();}ctx.event("POLICY_WAIT_END",&json!({"goal_id":goal_id,"reason":"pending relations adopted","parent_node":s.last_relation_node}));}}
pub fn record_size(state:&Shared,ctx:&Context){ctx.logical_buffer("dp02_public_adopted_view",snapshot(state).to_string().len(),"ALLOCATE_OR_REPLACE");let s=state.0.lock().unwrap();let owned=s.requests.values().map(|r|json!({"raw":r.raw,"adoption":r.adoption,"correction":r.correction,"delivered":r.delivered}).to_string().len()).sum::<usize>();ctx.logical_buffer("dp02_request_owned_semantic_states",owned,"ALLOCATE_OR_REPLACE");}
#[cfg(test)]mod tests{use super::*;#[test]fn captured_registry_is_not_adopted_goal(){let s=new();s.0.lock().unwrap().captured.push(json!({"id":"r","text":"x"}));assert!(s.0.lock().unwrap().requests.is_empty());}#[test]fn revision_scope_preserves_raw_request(){let r=Request{goal_id:"r".into(),stimulus_id:"r".into(),raw:"compare all".into(),revision:2,scope:"cost only".into(),adoption:json!({}),correction:Some(json!({"text":"cost only"})),delivered:None};assert_eq!(r.raw,"compare all");assert_eq!(r.scope,"cost only");}}

pub fn mark_response_attempt(state:&Shared,goal:&str,revision:u64){state.0.lock().unwrap().attempted_response_revision.insert(goal.into(),revision);}
pub fn needs_reopen(r:&Request,attempted:Option<u64>)->bool{r.delivered.is_none()&&r.correction.is_some()&&attempted.is_none_or(|prior|prior<r.revision)}
#[cfg(test)]mod reopen_tests{use super::*;fn corrected()->Request{Request{goal_id:"r".into(),stimulus_id:"r".into(),raw:"compare".into(),revision:2,scope:"cost".into(),adoption:json!({}),correction:Some(json!({})),delivered:None}}#[test]fn failed_same_revision_cannot_create_third_attempt(){assert!(!needs_reopen(&corrected(),Some(2)));}#[test]fn actually_new_revision_can_resume_after_old_terminal(){assert!(needs_reopen(&corrected(),Some(1)));assert!(needs_reopen(&corrected(),None));}}

#[cfg(test)]mod privacy_tests{use super::*;#[test]fn private_complete_answer_not_in_public_view(){let state=new();state.0.lock().unwrap().requests.insert("r".into(),Request{goal_id:"r".into(),stimulus_id:"r".into(),raw:"compare".into(),revision:1,scope:"cost".into(),adoption:json!({"relation":"NEW","complete_answer":"PRIVATE_UNSHOWN_DRAFT","source_claims":[{"quote":"PRIVATE_QUOTE"}]}),correction:None,delivered:None});let public=snapshot(&state).to_string();assert!(!public.contains("PRIVATE_UNSHOWN_DRAFT"));assert!(!public.contains("PRIVATE_QUOTE"));assert!(state.0.lock().unwrap().requests["r"].adoption["complete_answer"]=="PRIVATE_UNSHOWN_DRAFT");}}
